class Solution {
    public String trimReading(String num, int k) {
        StringBuilder s = new StringBuilder(num);
        for (int r = 0; r < k; r++) {
            int i = 0;
            while (i + 1 < s.length() && s.charAt(i) <= s.charAt(i + 1)) i++;
            s.deleteCharAt(i);
        }
        int z = 0;
        while (z < s.length() && s.charAt(z) == '0') z++;
        return z == s.length() ? "0" : s.substring(z);
    }
}

