char* trimReading(char* num, int k) {
    int len = strlen(num);
    char* s = malloc(len + 2);
    strcpy(s, num);
    for (int r = 0; r < k; r++) {
        int i = 0;
        while (i + 1 < len && s[i] <= s[i + 1]) i++;
        memmove(s + i, s + i + 1, len - i);
        len--;
    }
    int z = 0;
    while (z < len && s[z] == '0') z++;
    if (z == len) { strcpy(s, "0"); return s; }
    memmove(s, s + z, len - z + 1);
    return s;
}

