class Solution {
    public String trimReading(String num, int k) {
        StringBuilder stack = new StringBuilder();
        for (char d : num.toCharArray()) {
            while (k > 0 && stack.length() > 0 && stack.charAt(stack.length() - 1) > d) {
                stack.setLength(stack.length() - 1);
                k--;
            }
            stack.append(d);
        }
        stack.setLength(stack.length() - k);
        int z = 0;
        while (z < stack.length() && stack.charAt(z) == '0') z++;
        return z == stack.length() ? "0" : stack.substring(z);
    }
}

