class Solution {
public:
    string trimReading(string& num, int k) {
        string stack;
        for (char d : num) {
            while (k > 0 && !stack.empty() && stack.back() > d) {
                stack.pop_back();
                k--;
            }
            stack.push_back(d);
        }
        stack.resize(stack.size() - k);
        size_t z = stack.find_first_not_of('0');
        return z == string::npos ? "0" : stack.substr(z);
    }
};

