char* trimReading(char* num, int k) {
    int n = strlen(num), top = 0;
    char* stack = malloc(n + 2);
    for (int i = 0; i < n; i++) {
        while (k > 0 && top > 0 && stack[top - 1] > num[i]) {
            top--;
            k--;
        }
        stack[top++] = num[i];
    }
    top -= k;
    int z = 0;
    while (z < top && stack[z] == '0') z++;
    if (z == top) { strcpy(stack, "0"); return stack; }
    memmove(stack, stack + z, top - z);
    stack[top - z] = '\0';
    return stack;
}
